{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회의 원인을 실행 계획과 쿼리 구조에 근거해 좁힐 수 있는지 검증한다. 신고 목록 조회에서 병목을 특정한 결정적 근거 하나를 중심으로 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회에 3.2초가 걸렸던 상황.",
          "task": "신고 목록 조회가 느린 원인을 실행 계획에서 확인해 병목을 특정하는 것.",
          "action": "본인이 확인한 실행 계획의 신호를 실제 조회 조건이나 조인 구조와 연결해 해석하고, 그중 원인을 좁히는 데 결정적이었던 근거를 설명한다.",
          "result": "해당 근거로 어떤 조회 작업을 병목으로 판단했는지 드러나며, 단순한 추측과 구별되는 인과관계가 설명된다."
        },
        "expectedEvidence": [
          "신고 목록 조회의 병목을 특정하는 데 결정적이었던 실행 계획상의 근거",
          "그 근거가 실제 쿼리의 조회 조건 또는 조인 구조와 연결되는 방식",
          "해당 작업이 조회 지연을 일으킨다고 판단한 이유"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회를 3.2초에서 0.4초로 줄이셨네요. 실행 계획에서 조회 지연의 원인을 좁힌 결정적 근거는 무엇이었나요?",
      "answerTip": "당시 본 실행 계획의 모습부터 말해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "병목을 특정한 결정적 근거를 실행 계획에서 실제로 확인한 내용으로 명확히 제시한다.",
            "실행 계획의 신호를 해당 쿼리의 조회 조건 또는 조인 구조와 구체적으로 연결한다.",
            "그 작업이 지연을 유발한다고 판단한 이유를 설명해 원인 추론의 타당성이 확인된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "병목을 특정한 근거는 제시하지만 실행 계획에서 확인한 내용이 다소 포괄적이다.",
            "쿼리 구조와 조회 지연의 관련성은 설명하지만, 해당 근거가 결정적이었던 이유는 충분하지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "병목을 특정한 근거를 제시하지 않고 인덱스 추가나 속도 개선 결과만 설명한다.",
            "실행 계획에서 관찰한 사실과 원인 추측을 구분하지 못하거나, 쿼리 구조와 지연의 연결을 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "배포 후 발생한 오류를 로그로 추적해 원인 가설을 좁힐 수 있는지 검증한다. 알림 중복 발송을 클라이언트 문제가 아닌 스케줄러 중복 실행으로 판단한 이유를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 같은 알림이 두 번 발송된다는 문의를 받았고, 처음에는 클라이언트 문제를 의심했던 상황.",
          "task": "알림 중복 발송의 원인을 로그에서 확인해 발생 지점을 좁히는 것.",
          "action": "시간순으로 확인한 로그에서 두 서버의 스케줄러 실행과 관련된 관찰 내용을 제시하고, 초기 가설 대신 중복 실행을 원인으로 본 판단을 설명한다.",
          "result": "로그의 관찰 사실이 스케줄러 중복 실행이라는 결론을 어떻게 뒷받침했는지 드러난다."
        },
        "expectedEvidence": [
          "클라이언트 문제가 아니라 스케줄러 중복 실행을 원인으로 판단한 이유",
          "시간순으로 확인한 로그에서 그 판단을 뒷받침한 구체적인 관찰 사실",
          "관찰한 실행 기록과 알림 중복 발송 사이의 인과관계"
        ]
      },
      "question": "포켓마켓에서 배포 다음 날 알림이 두 번 발송되는 문의를 받으셨네요. 클라이언트가 아니라 스케줄러 중복 실행을 원인으로 본 판단을 들려주세요.",
      "answerTip": "처음 생각과 로그를 본 뒤의 생각을 나눠 말해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "스케줄러 중복 실행을 원인으로 본 판단을 초기 클라이언트 가설과 구별해 명확히 설명한다.",
            "시간순 로그에서 확인한 실행 기록을 구체적으로 제시해 판단을 뒷받침한다.",
            "두 서버의 스케줄러 실행이 알림 중복 발송으로 이어졌다고 본 이유를 논리적으로 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "스케줄러 중복 실행을 원인으로 판단한 이유는 설명하지만 초기 가설을 바꾼 이유가 충분히 드러나지 않는다.",
            "관련 로그를 확인했다고 설명하나 관찰 내용이나 중복 발송과의 연결이 일부 불명확하다."
          ]
        },
        "poor": {
          "criteria": [
            "원인으로 본 판단은 설명하지 않고 스케줄러가 중복 실행됐다는 결론이나 잠금 적용만 말한다.",
            "로그에서 확인한 사실을 제시하지 못하거나, 실행 기록이 알림 중복 발송을 설명하는 이유가 드러나지 않는다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "사용자 요청의 목적에 비추어 구현할 요구사항의 범위를 구체화할 수 있는지 검증한다. 개발 담당 팀원과 범위를 조정한 경험에서 개발 범위를 정한 기준 하나에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 세탁소 인터뷰를 바탕으로 요구사항 정의서를 작성하고 개발 담당 팀원과 범위를 조정한 상황이다.",
          "task": "인터뷰에서 확인한 요구 중 서비스 목적에 필요한 개발 범위의 경계를 정해야 했다.",
          "action": "실제 요구사항을 사례로 들어 개발 범위를 정한 기준을 설명하고, 그 기준이 사용자 요청의 목적과 어떻게 연결되는지 밝힌다.",
          "result": "해당 기준에 따라 정해진 개발 범위가 구체적으로 드러난다. 별도의 출시 성과나 수치는 요구하지 않는다."
        },
        "expectedEvidence": [
          "요구사항의 개발 범위를 정한 구체적인 판단 기준",
          "그 기준을 뒷받침하는 인터뷰 요청의 목적이나 범위 제약",
          "해당 기준을 실제 요구사항에 적용해 정한 범위의 경계"
        ]
      },
      "question": "동네 세탁소 예약 서비스에서 개발 담당 팀원과 범위를 조정하셨네요. 요구사항의 개발 범위를 정한 기준은 무엇이었나요?",
      "answerTip": "당시 요구 하나를 짚고 선택 전후를 나눠 말해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "개발 범위를 정한 기준을 구체적으로 설명한다.",
            "그 기준이 인터뷰에서 파악한 요청의 목적이나 실제 범위 제약과 연결된다.",
            "실제 요구사항에 기준을 적용한 설명을 통해 포함 범위와 제외 범위의 경계가 명확히 드러난다."
          ]
        },
        "acceptable": {
          "criteria": [
            "개발 범위를 정한 기준은 제시하지만 포괄적이거나 적용 방식이 모호하다.",
            "요청의 목적이나 범위 제약을 언급하지만 판단 기준과의 연결이 충분하지 않다.",
            "범위 조정 사례는 있으나 어디까지 구현하기로 했는지 경계가 일부만 드러난다."
          ]
        },
        "poor": {
          "criteria": [
            "개발 범위를 정한 기준을 설명하지 못하거나 요구사항 목록만 나열한다.",
            "판단을 뒷받침하는 사용자 요청이나 범위 제약이 드러나지 않는다.",
            "본인의 범위 판단 없이 개발 담당 팀원이 정했다는 설명에 그친다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "기능의 예외 상황을 구현 가능한 화면 상태로 구체화할 수 있는지 검증한다. 화면설계서에 포함한 예외 상황에서 사용자가 보게 될 화면 상태를 그렇게 설계한 이유에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 예약·취소·알림 흐름과 예외 상황을 포함한 화면설계서 28장을 작성한 상황이다.",
          "task": "예외 상황에서도 사용자가 자신의 상태를 이해할 수 있도록 해당 상황의 화면 상태를 구체화해야 했다.",
          "action": "실제로 다룬 예외 상황 하나를 중심으로 화면 상태를 정한 이유를 설명하고, 그 선택이 해당 기능 흐름에서 갖는 의미를 밝힌다.",
          "result": "예외 발생 시 사용자가 보게 되는 화면 상태가 분명해지고, 설계 이유와 화면 표현 사이의 연결이 드러난다. 실제 구현이나 사용자 검증 성과는 요구하지 않는다."
        },
        "expectedEvidence": [
          "예외 상황의 화면 상태를 그렇게 설계한 구체적인 이유",
          "그 판단의 전제가 된 예외 발생 조건과 기능 흐름",
          "설계 이유가 실제 화면 상태나 안내 표현에 반영된 구체적인 사례"
        ]
      },
      "question": "동네 세탁소 예약 서비스의 화면설계서 28장을 작성하셨네요. 예외 상황에서 사용자가 보게 될 화면 상태를 그렇게 설계한 이유는 무엇이었나요?",
      "answerTip": "예외 장면 하나를 떠올려 화면 모습과 이유를 연결해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "예외 상황의 화면 상태를 선택한 이유가 구체적이고 명확하다.",
            "해당 예외의 발생 조건과 기능 흐름이 화면 상태에 대한 판단을 뒷받침한다.",
            "실제 화면 상태나 안내 표현을 통해 설계 이유가 어떻게 반영됐는지 구현 가능한 수준으로 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "화면 상태를 선택한 이유는 설명하지만 사용자 편의 등 포괄적인 수준에 머문다.",
            "예외 발생 조건이나 기능 흐름을 일부 설명하지만 화면 상태와의 연결이 부족하다.",
            "화면 표현 사례는 있으나 예외 발생 시 사용자가 보게 되는 상태가 일부 모호하다."
          ]
        },
        "poor": {
          "criteria": [
            "화면 상태를 그렇게 설계한 이유를 제시하지 못하고 화면 구성만 나열한다.",
            "예외 발생 조건을 설명하지 않거나 정상 흐름에 대한 설명으로 벗어난다.",
            "화면 상태에 관한 구체적인 설명이 없어 예외 상황을 설계했는지 확인하기 어렵다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "의심스러운 처방을 그대로 수행하지 않고 확인하는 안전 행동을 검증한다. 평소 용량의 두 배로 나온 진통제 처방에 대해 담당의 확인이 필요하다고 판단한 이유를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동 근무 중 수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 나온 상황이다.",
          "task": "해당 처방을 그대로 수행해도 되는지, 투약을 보류하고 확인해야 하는지 판단해야 했다.",
          "action": "처방에서 의심한 지점과 당시 확인된 정보를 바탕으로, 담당의 확인 전에는 투약하지 않기로 판단한 이유를 설명한다.",
          "result": "담당의 확인을 통해 입력 오류였음이 밝혀진 사실이 당시 판단의 타당성을 뒷받침한다."
        },
        "expectedEvidence": [
          "담당의 확인 전 투약을 멈춰야 한다고 판단한 구체적인 이유",
          "평소 용량과 해당 처방의 차이 등 처방의 정확성을 의심하게 된 사실",
          "용량 차이를 임의로 해석해 투약하지 않고 처방 확인이 필요하다고 본 이유"
        ]
      },
      "question": "평소 용량의 두 배로 나온 수술 후 환자의 진통제 처방에서 투약을 멈추셨네요. 담당의 확인이 필요하다고 판단한 이유는 무엇이었나요?",
      "answerTip": "당시 본 처방과 비교한 정보를 나눠 말해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "담당의 확인이 필요하다고 판단한 이유를 당시 처방의 구체적인 의심 지점과 연결해 설명한다.",
            "평소 용량과의 차이가 처방의 정확성을 재확인해야 할 신호였음을 당시 확인된 정보로 뒷받침한다.",
            "의심을 해소하지 않은 채 투약하거나 용량을 임의로 바꾸지 않아야 하는 이유가 명확하다."
          ]
        },
